import Model from 'flarum/common/Model';
export default class Vote extends Model {
  createdAt = Model.attribute('createdAt', Model.transformDate);

  // Direct attribute access for IDs (for when relationships aren't loaded)
  nomineeId = Model.attribute('nomineeId');
  categoryId = Model.attribute('categoryId');
  userId = Model.attribute('userId');

  // Relationship accessors
  nominee = Model.hasOne('nominee');
  category = Model.hasOne('category');
  user = Model.hasOne('user');
  relationshipId(name) {
    const data = this.data.relationships?.[name]?.data;
    return data && !Array.isArray(data) ? data.id : undefined;
  }
}
flarum.reg.add('huseyinfiliz-awards', 'common/models/Vote', Vote);