import Model from 'flarum/common/Model';
export default class OtherSuggestion extends Model {
  name = Model.attribute('name');
  status = Model.attribute('status');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  updatedAt = Model.attribute('updatedAt', Model.transformDate);
  category = Model.hasOne('category');
  user = Model.hasOne('user');
  mergedToNominee = Model.hasOne('mergedToNominee');
  isPending() {
    return this.status() === 'pending';
  }
  isApproved() {
    return this.status() === 'approved';
  }
  isRejected() {
    return this.status() === 'rejected';
  }
  isMerged() {
    return this.status() === 'merged';
  }
}
flarum.reg.add('huseyinfiliz-awards', 'common/models/OtherSuggestion', OtherSuggestion);